 public static void ResetLessons()=>learned.Clear();
 ShipController ship;FishPilot fish;ShipUIManager loot;ShipWaterPurification water;Text text;Image panel;VoyageGuideArrow arrow;string lesson;float visibleTime,originalDash,originalWater;Vector2 start;bool originalLoot,observed;
 void Start(){ship=FindFirstObjectByType<ShipController>();fish=FindFirstObjectByType<FishPilot>();loot=FindFirstObjectByType<ShipUIManager>();if(ship)water=ship.GetComponent<ShipWaterPurification>();panel=Picture("First use controls",root,Vector2.zero,new Vector2(950,125),"button");panel.raycastTarget=false;panel.rectTransform.anchorMin=panel.rectTransform.anchorMax=new Vector2(.5f,1);panel.rectTransform.anchoredPosition=new Vector2(0,ship?((float)Screen.width/Screen.height<1.7f?-650:-180):-230);text=Label("Control instructions",panel.transform,Vector2.zero,new Vector2(850,100),"",26);panel.gameObject.SetActive(false);var r=Rect("Green tutorial arrow",root,Vector2.zero,new Vector2(80,90));r.gameObject.AddComponent<CanvasRenderer>();arrow=r.gameObject.AddComponent<VoyageGuideArrow>();arrow.color=new Color(.22f,1,.27f);arrow.raycastTarget=false;arrow.gameObject.SetActive(false);}
 void PointTo(RectTransform target){if(!target){arrow.gameObject.SetActive(false);return;}var corners=new Vector3[4];target.GetWorldCorners(corners);var canvas=target.GetComponentInParent<Canvas>();var camera=canvas.renderMode==RenderMode.ScreenSpaceOverlay?null:canvas.worldCamera;var right=RectTransformUtility.WorldToScreenPoint(camera,(corners[2]+corners[3])*.5f);var at=right+Vector2.right*(55+Mathf.Sin(Time.unscaledTime*4)*6);RectTransformUtility.ScreenPointToLocalPointInRectangle((RectTransform)arrow.transform.parent,at,null,out var local);arrow.rectTransform.anchoredPosition=local;arrow.rectTransform.localRotation=Quaternion.Euler(0,0,-90);arrow.gameObject.SetActive(true);}
 void Update(){if(!panel)return;if(ship&&!water)water=ship.GetComponent<ShipWaterPurification>();arrow.gameObject.SetActive(false);bool ready=Time.timeScale>0&&!VoyagePauseMenu.IsOpen&&!StorySceneJourney.Instance.IsTransitioning&&(fish&&!fish.ControlsLocked||ship&&ship.enabled);var story=FindFirstObjectByType<UnderwaterStoryUI>();if(story&&story.Active)ready=false;if(!ready){panel.gameObject.SetActive(false);return;}
 string prefix=ship?"ship.":"fish.";string next=ship?(!learned.Contains("ship.loot")?"loot":!learned.Contains("ship.purify")?"purify":StorySceneJourney.Instance.Stage==JourneyStage.FirstShip&&!learned.Contains("ship.energy")?"energy":!learned.Contains("ship.boost")?"boost":""):!learned.Contains("fish.move")?"move":"";
 if(next==""){panel.gameObject.SetActive(false);return;}string key=prefix+next;if(lesson!=key){lesson=key;visibleTime=0;observed=false;start=ship?(Vector2)ship.transform.position:(Vector2)fish.transform.position;originalLoot=loot&&loot.isLootingXP;originalDash=ship?ship.currentDash:0;originalWater=water?water.NormalizedProgress:0;text.text=next=="loot"?"Toplayacağın ödülü seçmek için enerji veya XP göstergesine dokun.":next=="purify"?"Kasabaya temiz su götürmek için deniz suyunu arıtmalısın. Arıtmak için gemiyle ilerle.":next=="energy"?"Yolda kalmamak için enerjine dikkat et. Denizdeki şimşekleri toplayarak enerjini yenile.":next=="boost"?(VoyageTouchInput.Enabled?"Gemi düğmesine dokunarak atılım yap.":"Shift • Atılım yap"):VoyageTouchInput.Enabled?"Sol joystick ile yüz.":"WASD • Yüz";}
 panel.gameObject.SetActive(true);visibleTime+=Time.deltaTime;if(next=="loot"){var view=FindFirstObjectByType<OrbRewardToggleView>();if(view)PointTo((RectTransform)view.transform);}else if(next=="purify"&&water&&water.percentage)PointTo(water.percentage.rectTransform);else if(next=="energy"&&loot&&loot.energyFill)PointTo(loot.energyFill.rectTransform);
 bool done=next=="energy"?visibleTime>=7:next=="move"?Vector2.Distance(start,fish.transform.position)>1.2f:next=="boost"?ship.IsDashing||ship.currentDash<originalDash-.4f:next=="purify"?water&&water.NormalizedProgress>originalWater+.015f:loot&&loot.isLootingXP!=originalLoot;observed|=done;if(visibleTime>(next=="purify"?4:3)&&observed||visibleTime>14){learned.Add(key);panel.gameObject.SetActive(false);arrow.gameObject.SetActive(false);}
 }
